"""Order fulfillment service: SQLite-backed orders with stock reservation."""

from __future__ import annotations

import math
import sqlite3

__all__ = ["OrderError", "OrderService"]

_BUSY_TIMEOUT_MS = 15000

_SCHEMA = {
    "stock": {"sku", "available"},
    "orders": {
        "order_id",
        "idempotency_key",
        "status",
        "total_cents",
        "payment_id",
        "amount_cents",
        "created_at",
        "updated_at",
    },
    "order_items": {"order_id", "sku", "quantity", "unit_price_cents"},
    "payments": {"payment_id", "order_id", "amount_cents"},
}

_DDL = """
CREATE TABLE stock (
    sku TEXT PRIMARY KEY,
    available INTEGER NOT NULL CHECK (available >= 0)
);
CREATE TABLE orders (
    order_id TEXT PRIMARY KEY,
    idempotency_key TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),
    total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
    payment_id TEXT,
    amount_cents INTEGER,
    created_at,
    updated_at
);
CREATE TABLE order_items (
    order_id TEXT NOT NULL REFERENCES orders(order_id),
    sku TEXT NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
    PRIMARY KEY (order_id, sku)
);
CREATE TABLE payments (
    payment_id TEXT PRIMARY KEY,
    order_id TEXT NOT NULL REFERENCES orders(order_id),
    amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0)
);
"""

_ORDER_COLUMNS = (
    "order_id",
    "idempotency_key",
    "status",
    "total_cents",
    "payment_id",
    "created_at",
    "updated_at",
)


class OrderError(Exception):
    """Stable order-domain error with code, message and details."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = dict(details) if details else {}


def _error(code: str, message: str, details: dict[str, object] | None = None) -> OrderError:
    return OrderError(code, message, details)


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _require_id(value: object, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise _error(
            "INVALID_INPUT",
            f"{field} must be a non-empty, non-whitespace string",
            {"field": field},
        )
    return value


def _require_finite_clock_value(value: object) -> object:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise _error("INVALID_DEPENDENCY", "clock returned a non-finite number", {})
    return value


def _now(clock) -> object:
    try:
        value = clock()
    except Exception as exc:  # dependency failure
        raise _error("INVALID_DEPENDENCY", "clock raised an exception", {"reason": str(exc)}) from exc
    return _require_finite_clock_value(value)


def _validate_items(items: object) -> list[tuple[str, int, int]]:
    if not isinstance(items, list) or not items:
        raise _error("INVALID_INPUT", "items must be a non-empty list", {"field": "items"})
    canonical: list[tuple[str, int, int]] = []
    seen: set[str] = set()
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise _error("INVALID_INPUT", "each item must be an object", {"index": index})
        if set(item.keys()) != {"sku", "quantity", "unit_price_cents"}:
            raise _error("INVALID_INPUT", "item fields must be exactly sku, quantity, unit_price_cents", {"index": index})
        sku = item["sku"]
        if not isinstance(sku, str) or not sku.strip():
            raise _error("INVALID_INPUT", "item sku must be a non-empty, non-whitespace string", {"index": index})
        quantity = item["quantity"]
        if not _is_int(quantity) or quantity <= 0:
            raise _error("INVALID_INPUT", "item quantity must be an integer greater than zero", {"index": index})
        price = item["unit_price_cents"]
        if not _is_int(price) or price < 0:
            raise _error("INVALID_INPUT", "item unit_price_cents must be an integer greater than or equal to zero", {"index": index})
        if sku in seen:
            raise _error("INVALID_INPUT", "duplicate sku in items", {"sku": sku})
        seen.add(sku)
        canonical.append((sku, quantity, price))
    canonical.sort(key=lambda triple: triple[0])
    return canonical


class OrderService:
    """SQLite-backed order service with atomic reservation and idempotency."""

    def __init__(self, db_path, *, clock, id_factory):
        try:
            conn = sqlite3.connect(
                db_path,
                isolation_level=None,
                timeout=_BUSY_TIMEOUT_MS / 1000.0,
                check_same_thread=False,
            )
        except Exception as exc:
            raise _error("STORAGE_ERROR", "could not open database", {"reason": str(exc)}) from exc
        self._conn = conn
        self._clock = clock
        self._id_factory = id_factory
        try:
            conn.execute(f"PRAGMA busy_timeout = {_BUSY_TIMEOUT_MS}")
            conn.execute("PRAGMA foreign_keys = ON")
            self._prepare_schema(conn)
        except OrderError:
            conn.close()
            raise
        except Exception as exc:
            conn.close()
            raise _error("STORAGE_ERROR", "could not prepare schema", {"reason": str(exc)}) from exc

    @staticmethod
    def _prepare_schema(conn: sqlite3.Connection) -> None:
        tables = {
            row[0]
            for row in conn.execute(
                "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'"
            )
        }
        if not tables:
            conn.executescript(_DDL)
            return
        if tables != set(_SCHEMA):
            raise _error("SCHEMA_MISMATCH", "database tables do not match the expected schema", {"tables": sorted(tables)})
        for table, expected_columns in _SCHEMA.items():
            actual = {row[1] for row in conn.execute(f"PRAGMA table_info({table})")}
            if actual != expected_columns:
                raise _error(
                    "SCHEMA_MISMATCH",
                    f"table {table} does not match the expected schema",
                    {"table": table},
                )

    def _txn(self, fn):
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "could not begin transaction", {"reason": str(exc)}) from exc
        try:
            result = fn(conn)
        except sqlite3.Error as exc:
            self._rollback()
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc
        except BaseException:
            self._rollback()
            raise
        try:
            conn.execute("COMMIT")
        except sqlite3.Error as exc:
            self._rollback()
            raise _error("STORAGE_ERROR", "could not commit transaction", {"reason": str(exc)}) from exc
        return result

    def _rollback(self) -> None:
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    def _order_dict(self, conn: sqlite3.Connection, order_id: str) -> dict:
        row = conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
            "FROM orders WHERE order_id = ?",
            (order_id,),
        ).fetchone()
        if row is None:
            raise _error("NOT_FOUND", "order not found", {"order_id": order_id})
        item_rows = conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
            (order_id,),
        ).fetchall()
        return {
            "order_id": row[0],
            "idempotency_key": row[1],
            "status": row[2],
            "items": [
                {"sku": item[0], "quantity": item[1], "unit_price_cents": item[2]}
                for item in item_rows
            ],
            "total_cents": row[3],
            "payment_id": row[4],
            "created_at": row[5],
            "updated_at": row[6],
        }

    def _fetch_order(self, conn: sqlite3.Connection, order_id: str):
        row = conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, amount_cents, "
            "created_at, updated_at FROM orders WHERE order_id = ?",
            (order_id,),
        ).fetchone()
        if row is None:
            raise _error("NOT_FOUND", "order not found", {"order_id": order_id})
        return row

    def _generate_order_id(self, conn: sqlite3.Connection) -> str:
        for _ in range(3):
            try:
                candidate = self._id_factory()
            except Exception as exc:
                raise _error("INVALID_DEPENDENCY", "id_factory raised an exception", {"reason": str(exc)}) from exc
            if not isinstance(candidate, str) or not candidate.strip():
                raise _error("INVALID_DEPENDENCY", "id_factory returned an invalid value", {})
            if conn.execute("SELECT 1 FROM orders WHERE order_id = ?", (candidate,)).fetchone() is None:
                return candidate
        raise _error("ID_COLLISION", "id_factory produced only duplicate order ids", {})

    def set_stock(self, sku: str, quantity: int) -> dict:
        sku = _require_id(sku, "sku")
        if not _is_int(quantity) or quantity < 0:
            raise _error("INVALID_INPUT", "quantity must be an integer greater than or equal to zero", {"field": "quantity"})
        try:
            self._conn.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                (sku, quantity),
            )
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "could not set stock", {"reason": str(exc)}) from exc
        return {"sku": sku, "available": quantity}

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        key = _require_id(idempotency_key, "idempotency_key")
        canonical = _validate_items(items)
        total_cents = sum(quantity * price for _, quantity, price in canonical)

        def run(conn: sqlite3.Connection) -> dict:
            existing = conn.execute(
                "SELECT order_id FROM orders WHERE idempotency_key = ?", (key,)
            ).fetchone()
            if existing is not None:
                stored = conn.execute(
                    "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
                    (existing[0],),
                ).fetchall()
                if [tuple(row) for row in stored] == canonical:
                    return self._order_dict(conn, existing[0])
                raise _error(
                    "IDEMPOTENCY_CONFLICT",
                    "idempotency key already used with different items",
                    {"idempotency_key": key},
                )
            for sku, quantity, _ in canonical:
                row = conn.execute("SELECT available FROM stock WHERE sku = ?", (sku,)).fetchone()
                if row is None or row[0] < quantity:
                    raise _error("INSUFFICIENT_STOCK", "insufficient stock", {"sku": sku})
            order_id = self._generate_order_id(conn)
            now = _now(self._clock)
            conn.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents, payment_id, "
                "amount_cents, created_at, updated_at) VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)",
                (order_id, key, total_cents, now, now),
            )
            conn.executemany(
                "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents) VALUES (?, ?, ?, ?)",
                [(order_id, sku, quantity, price) for sku, quantity, price in canonical],
            )
            for sku, quantity, _ in canonical:
                conn.execute("UPDATE stock SET available = available - ? WHERE sku = ?", (quantity, sku))
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        order_id = _require_id(order_id, "order_id")
        payment_id = _require_id(payment_id, "payment_id")
        if not _is_int(amount_cents) or amount_cents < 0:
            raise _error("INVALID_INPUT", "amount_cents must be an integer greater than or equal to zero", {"field": "amount_cents"})

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            recorded = conn.execute(
                "SELECT order_id, amount_cents FROM payments WHERE payment_id = ?", (payment_id,)
            ).fetchone()
            if recorded is not None:
                if recorded[0] != order_id or recorded[1] != amount_cents:
                    raise _error(
                        "PAYMENT_CONFLICT",
                        "payment id already used with a different order or amount",
                        {"payment_id": payment_id},
                    )
                return self._order_dict(conn, order_id)
            if status != "pending":
                if row[4] is not None:
                    raise _error(
                        "PAYMENT_CONFLICT",
                        "order already paid with a different payment id",
                        {"order_id": order_id},
                    )
                raise _error("INVALID_STATE", f"cannot pay order in status {status}", {"status": status})
            if amount_cents != row[3]:
                raise _error(
                    "AMOUNT_MISMATCH",
                    "amount does not match order total",
                    {"expected": row[3], "actual": amount_cents},
                )
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'paid', payment_id = ?, amount_cents = ?, updated_at = ? "
                "WHERE order_id = ?",
                (payment_id, amount_cents, now, order_id),
            )
            conn.execute(
                "INSERT INTO payments (payment_id, order_id, amount_cents) VALUES (?, ?, ?)",
                (payment_id, order_id, amount_cents),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def cancel_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            if status == "cancelled":
                return self._order_dict(conn, order_id)
            if status == "shipped":
                raise _error("INVALID_STATE", "cannot cancel a shipped order", {"status": status})
            items = conn.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?", (order_id,)
            ).fetchall()
            for sku, quantity in items:
                conn.execute(
                    "INSERT INTO stock (sku, available) VALUES (?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET available = stock.available + excluded.available",
                    (sku, quantity),
                )
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def ship_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            if status == "shipped":
                return self._order_dict(conn, order_id)
            if status != "paid":
                raise _error("INVALID_STATE", f"cannot ship order in status {status}", {"status": status})
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def get_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")
        try:
            return self._order_dict(self._conn, order_id)
        except OrderError:
            raise
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

