            if conn.execute("SELECT 1 FROM orders WHERE order_id = ?", (candidate,)).fetchone() is None:
                return candidate
        raise _error("ID_COLLISION", "id_factory produced only duplicate order ids", {})

    def set_stock(self, sku: str, quantity: int) -> dict:
        sku = _require_id(sku, "sku")
        if not _is_int(quantity) or quantity < 0:
            raise _error("INVALID_INPUT", "quantity must be an integer greater than or equal to zero", {"field": "quantity"})
        try:
            self._conn.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                (sku, quantity),
            )
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "could not set stock", {"reason": str(exc)}) from exc
        return {"sku": sku, "available": quantity}

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        key = _require_id(idempotency_key, "idempotency_key")
        canonical = _validate_items(items)
        total_cents = sum(quantity * price for _, quantity, price in canonical)

        def run(conn: sqlite3.Connection) -> dict:
            existing = conn.execute(
                "SELECT order_id FROM orders WHERE idempotency_key = ?", (key,)
            ).fetchone()
            if existing is not None:
                stored = conn.execute(
                    "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
                    (existing[0],),
                ).fetchall()
                if [tuple(row) for row in stored] == canonical:
                    return self._order_dict(conn, existing[0])
                raise _error(
                    "IDEMPOTENCY_CONFLICT",
                    "idempotency key already used with different items",
                    {"idempotency_key": key},
                )
            for sku, quantity, _ in canonical:
                row = conn.execute("SELECT available FROM stock WHERE sku = ?", (sku,)).fetchone()
                if row is None or row[0] < quantity:
                    raise _error("INSUFFICIENT_STOCK", "insufficient stock", {"sku": sku})
            order_id = self._generate_order_id(conn)
            now = _now(self._clock)
            conn.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents, payment_id, "
                "amount_cents, created_at, updated_at) VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)",
                (order_id, key, total_cents, now, now),
            )
            conn.executemany(
                "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents) VALUES (?, ?, ?, ?)",
                [(order_id, sku, quantity, price) for sku, quantity, price in canonical],
            )
            for sku, quantity, _ in canonical:
                conn.execute("UPDATE stock SET available = available - ? WHERE sku = ?", (quantity, sku))
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        order_id = _require_id(order_id, "order_id")
        payment_id = _require_id(payment_id, "payment_id")
        if not _is_int(amount_cents) or amount_cents < 0:
            raise _error("INVALID_INPUT", "amount_cents must be an integer greater than or equal to zero", {"field": "amount_cents"})

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            recorded = conn.execute(
                "SELECT order_id, amount_cents FROM payments WHERE payment_id = ?", (payment_id,)
            ).fetchone()
            if recorded is not None:
                if recorded[0] != order_id or recorded[1] != amount_cents:
                    raise _error(
                        "PAYMENT_CONFLICT",
                        "payment id already used with a different order or amount",
                        {"payment_id": payment_id},
                    )
                return self._order_dict(conn, order_id)
            if status != "pending":
                if row[4] is not None:
                    raise _error(
                        "PAYMENT_CONFLICT",
                        "order already paid with a different payment id",
                        {"order_id": order_id},
                    )
                raise _error("INVALID_STATE", f"cannot pay order in status {status}", {"status": status})
            if amount_cents != row[3]:
                raise _error(
                    "AMOUNT_MISMATCH",
                    "amount does not match order total",
                    {"expected": row[3], "actual": amount_cents},
                )
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'paid', payment_id = ?, amount_cents = ?, updated_at = ? "
                "WHERE order_id = ?",
                (payment_id, amount_cents, now, order_id),
            )
            conn.execute(
                "INSERT INTO payments (payment_id, order_id, amount_cents) VALUES (?, ?, ?)",
                (payment_id, order_id, amount_cents),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def cancel_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            if status == "cancelled":
                return self._order_dict(conn, order_id)
            if status == "shipped":
                raise _error("INVALID_STATE", "cannot cancel a shipped order", {"status": status})
            items = conn.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?", (order_id,)
            ).fetchall()
            for sku, quantity in items:
                conn.execute(
                    "INSERT INTO stock (sku, available) VALUES (?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET available = stock.available + excluded.available",
                    (sku, quantity),
                )
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def ship_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")

        def run(conn: sqlite3.Connection) -> dict:
            row = self._fetch_order(conn, order_id)
            status = row[2]
            if status == "shipped":
                return self._order_dict(conn, order_id)
            if status != "paid":
                raise _error("INVALID_STATE", f"cannot ship order in status {status}", {"status": status})
            now = _now(self._clock)
            conn.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            return self._order_dict(conn, order_id)

        try:
            return self._txn(run)
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

    def get_order(self, order_id: str) -> dict:
        order_id = _require_id(order_id, "order_id")
        try:
            return self._order_dict(self._conn, order_id)
        except OrderError:
            raise
        except sqlite3.Error as exc:
            raise _error("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc

