"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time
import uuid

from . import OrderError, OrderService

_COMMAND_FIELDS = {
    "stock": ("sku", "quantity"),
    "create": ("idempotency_key", "items"),
    "pay": ("order_id", "payment_id", "amount_cents"),
    "cancel": ("order_id",),
    "ship": ("order_id",),
    "get": ("order_id",),
}


def _emit(payload: object) -> None:
    text = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    sys.stdout.buffer.write(text.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()


def _fail(code: str, message: str, details: dict[str, object] | None = None) -> int:
    _emit({"ok": False, "error": {"code": code, "message": message, "details": details or {}}})
    return 3 if code == "STORAGE_ERROR" else 2


def _parse_args(argv: list[str]):
    db_path = None
    rest: list[str] = []
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--db":
            if index + 1 >= len(argv):
                return None, None
            db_path = argv[index + 1]
            index += 2
        else:
            rest.append(arg)
            index += 1
    if db_path is None or len(rest) != 1:
        return None, None
    return db_path, rest[0]


def _read_input() -> dict:
    raw = sys.stdin.buffer.read()
    text = raw.decode("utf-8")
    lines = [line for line in text.splitlines() if line.strip()]
    if len(lines) != 1:
        raise ValueError("expected exactly one non-empty stdin line")
    obj = json.loads(lines[0])
    if not isinstance(obj, dict):
        raise ValueError("stdin must be a JSON object")
    return obj


def main() -> None:
    db_path, command = _parse_args(sys.argv[1:])
    if db_path is None or command not in _COMMAND_FIELDS:
        sys.exit(_fail("INVALID_INPUT", "usage: python -m src.order_fulfillment --db <path> <command>", {}))
    try:
        obj = _read_input()
    except Exception as exc:
        sys.exit(_fail("INVALID_INPUT", f"invalid input: {exc}", {}))
    required = _COMMAND_FIELDS[command]
    if set(obj.keys()) != set(required):
        sys.exit(_fail(
            "INVALID_INPUT",
            f"command {command} expects exactly the fields {', '.join(required)}",
            {"command": command},
        ))
    try:
        service = OrderService(db_path, clock=time.time, id_factory=lambda: uuid.uuid4().hex)
        if command == "stock":
            result = service.set_stock(obj["sku"], obj["quantity"])
        elif command == "create":
            result = service.create_order(obj["idempotency_key"], obj["items"])
        elif command == "pay":
            result = service.pay_order(obj["order_id"], obj["payment_id"], obj["amount_cents"])
        elif command == "cancel":
            result = service.cancel_order(obj["order_id"])
        elif command == "ship":
            result = service.ship_order(obj["order_id"])
        else:
            result = service.get_order(obj["order_id"])
    except OrderError as exc:
        sys.exit(_fail(exc.code, exc.message, exc.details))
    except Exception as exc:
        sys.exit(_fail("STORAGE_ERROR", f"unexpected failure: {exc}", {}))
    _emit({"ok": True, "result": result})
    sys.exit(0)


if __name__ == "__main__":
    main()

