"""Delivery spool: filesystem-backed durable outbox with worker leases."""

from __future__ import annotations

import dataclasses
import hmac
import json
import math
import os
import secrets
import time
import uuid

if os.name == "nt":  # pragma: no cover - platform specific
    import msvcrt
else:  # pragma: no cover - platform specific
    import fcntl

__all__ = ["Limits", "Spool", "SpoolError"]

_STATE_FILE = "state.json"
_LOCK_FILE = "state.lock"
_SCHEMA_VERSION = 1
_STATUSES = ("pending", "leased", "acked", "dead")
_PUBLIC_FIELDS = frozenset(
    {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
)
_PRIVATE_FIELDS = frozenset({"lease_token", "worker_id", "expires_at"})


def _is_finite_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _is_positive_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


class SpoolError(Exception):
    """Stable spool-domain error with code, message and details."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = dict(details) if details else {}


def _error(code: str, message: str, details: dict[str, object] | None = None) -> SpoolError:
    return SpoolError(code, message, details)


class _DuplicateKey(Exception):
    pass


def _pairs_to_dict(pairs):
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _DuplicateKey(key)
        result[key] = value
    return result


def _canonical_dumps(value: object) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _require_id(value: object, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise _error(
            "INVALID_INPUT",
            f"{field} must be a non-empty, non-whitespace string",
            {"field": field},
        )
    return value


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        for name in ("max_messages", "max_payload_bytes", "max_attempts"):
            if not _is_positive_int(getattr(self, name)):
                raise _error("INVALID_INPUT", f"{name} must be a positive integer", {"field": name})
        if not _is_finite_number(self.lease_seconds) or self.lease_seconds <= 0:
            raise _error("INVALID_INPUT", "lease_seconds must be a finite number greater than zero", {"field": "lease_seconds"})
        if not _is_finite_number(self.retry_delay) or self.retry_delay < 0:
            raise _error("INVALID_INPUT", "retry_delay must be a finite number greater than or equal to zero", {"field": "retry_delay"})


class Spool:
    """Filesystem-backed lease spool with durable atomic commits."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if isinstance(root, os.PathLike):
            root = os.fspath(root)
        if not isinstance(root, str) or not root.strip():
            raise _error("INVALID_INPUT", "root must be a non-empty directory path", {"field": "root"})
        if not callable(clock):
            raise _error("INVALID_INPUT", "clock must be callable", {"field": "clock"})
        if not isinstance(limits, Limits):
            raise _error("INVALID_INPUT", "limits must be a Limits instance", {"field": "limits"})
        if not _is_finite_number(lock_timeout) or lock_timeout < 0:
            raise _error("INVALID_INPUT", "lock_timeout must be a finite number greater than or equal to zero", {"field": "lock_timeout"})
        if failpoint is not None and not callable(failpoint):
            raise _error("INVALID_INPUT", "failpoint must be None or callable", {"field": "failpoint"})
        self._root = root
        self._clock = clock
        self._limits = limits
        self._lock_timeout = lock_timeout
        self._failpoint = failpoint

    # -- internals -----------------------------------------------------

    def _state_path(self) -> str:
        return os.path.join(self._root, _STATE_FILE)

    def _lock_path(self) -> str:
        return os.path.join(self._root, _LOCK_FILE)

    def _fail(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    def _acquire_lock(self):
        try:
            fd = os.open(self._lock_path(), os.O_RDWR | os.O_CREAT, 0o644)
        except OSError as exc:
            raise _error("INTERNAL_ERROR", f"could not open lock file: {exc}", {}) from exc
        deadline = time.monotonic() + self._lock_timeout
        delay = 0.001
        while True:
            try:
                if os.name == "nt":
                    os.lseek(fd, 0, os.SEEK_SET)
                    msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                else:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return fd
            except OSError:
                if time.monotonic() >= deadline:
                    os.close(fd)
                    raise _error("LOCK_TIMEOUT", "timed out acquiring state lock", {"root": self._root})
                time.sleep(delay)
                delay = min(delay * 2, 0.02)

    def _release_lock(self, fd) -> None:
        try:
            if os.name == "nt":
                try:
                    os.lseek(fd, 0, os.SEEK_SET)
                    msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
                except OSError:
                    pass
        finally:
            os.close(fd)

    def _read_state(self) -> dict:
        try:
            with open(self._state_path(), "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            raise _error("NOT_INITIALIZED", "spool is not initialized", {"root": self._root})
        except OSError as exc:
            raise _error("CORRUPT_STATE", f"could not read state file: {exc}", {}) from exc
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise _error("CORRUPT_STATE", "state file is not valid UTF-8", {}) from exc
        try:
            state = json.loads(text, object_pairs_hook=_pairs_to_dict)
        except _DuplicateKey as exc:
            raise _error("CORRUPT_STATE", "state file contains duplicate JSON keys", {"key": str(exc)}) from exc
        except ValueError as exc:
            raise _error("CORRUPT_STATE", "state file is not valid JSON", {"reason": str(exc)}) from exc
        self._validate_state(state)
        if _canonical_dumps(state) + "\n" != text:
            raise _error("CORRUPT_STATE", "state file is not canonical JSON", {})
        return state

    def _validate_state(self, state: object) -> None:
        if not isinstance(state, dict):
            raise _error("CORRUPT_STATE", "state root must be a JSON object", {})
        if set(state.keys()) != {"schema_version", "next_sequence", "messages"}:
            raise _error("CORRUPT_STATE", "state has unknown or missing top-level fields", {})
        schema_version = state["schema_version"]
        if isinstance(schema_version, bool) or not isinstance(schema_version, int) or schema_version != _SCHEMA_VERSION:
            raise _error("SCHEMA_MISMATCH", "unknown schema_version", {"schema_version": schema_version})
        next_sequence = state["next_sequence"]
        if isinstance(next_sequence, bool) or not isinstance(next_sequence, int) or next_sequence < 1:
            raise _error("CORRUPT_STATE", "invalid next_sequence", {"next_sequence": next_sequence})
        messages = state["messages"]
        if not isinstance(messages, dict):
            raise _error("CORRUPT_STATE", "messages must be a JSON object", {})
        seen_sequences: set[int] = set()
        for message_id, message in messages.items():
            self._validate_message(message_id, message)
            sequence = message["sequence"]
            if sequence in seen_sequences:
                raise _error("CORRUPT_STATE", "duplicate message sequence", {"sequence": sequence})
            seen_sequences.add(sequence)
            if sequence >= next_sequence:
                raise _error("CORRUPT_STATE", "message sequence exceeds next_sequence", {"sequence": sequence})

    def _validate_message(self, message_id: object, message: object) -> None:
        if not isinstance(message, dict):
            raise _error("CORRUPT_STATE", "message record must be a JSON object", {})
        status = message.get("status")
        expected = _PUBLIC_FIELDS | _PRIVATE_FIELDS if status == "leased" else _PUBLIC_FIELDS
        if set(message.keys()) != expected:
            raise _error("CORRUPT_STATE", "message record has unknown or missing fields", {"message_id": message_id})
        if not isinstance(message_id, str) or not message_id.strip():
            raise _error("CORRUPT_STATE", "message id must be a non-empty string", {})
        if message["message_id"] != message_id:
            raise _error("CORRUPT_STATE", "message id mismatch", {"message_id": message_id})
        if status not in _STATUSES:
            raise _error("CORRUPT_STATE", "unknown message status", {"status": status})
        if not _is_finite_number(message["available_at"]):
            raise _error("CORRUPT_STATE", "invalid available_at", {"message_id": message_id})
        attempts = message["attempts"]
        if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 0:
            raise _error("CORRUPT_STATE", "invalid attempts", {"message_id": message_id})
        sequence = message["sequence"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise _error("CORRUPT_STATE", "invalid sequence", {"message_id": message_id})
        last_error = message["last_error"]
        if last_error is not None and not isinstance(last_error, str):
            raise _error("CORRUPT_STATE", "invalid last_error", {"message_id": message_id})
        if status == "leased":
            token = message["lease_token"]
            worker_id = message["worker_id"]
            if not isinstance(token, str) or not token:
                raise _error("CORRUPT_STATE", "invalid lease_token", {"message_id": message_id})
            if not isinstance(worker_id, str) or not worker_id.strip():
                raise _error("CORRUPT_STATE", "invalid worker_id", {"message_id": message_id})
            if not _is_finite_number(message["expires_at"]):
                raise _error("CORRUPT_STATE", "invalid expires_at", {"message_id": message_id})

    def _write_state(self, state: dict, temp_files: list[str]) -> None:
        data = _canonical_dumps(state) + "\n"
        temp_path = os.path.join(self._root, f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp")
        temp_files.append(temp_path)
        try:
            with open(temp_path, "w", encoding="utf-8", newline="") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
        except OSError as exc:
            raise _error("INTERNAL_ERROR", f"could not write temporary state: {exc}", {}) from exc
        self._fail("before_replace")
        try:
            os.replace(temp_path, self._state_path())
        except OSError as exc:
            raise _error("INTERNAL_ERROR", f"could not replace state file: {exc}", {}) from exc
        self._fail("after_replace")
        try:
            dir_fd = os.open(self._root, os.O_RDONLY)
        except OSError:
            dir_fd = None
        if dir_fd is not None:
            try:
                os.fsync(dir_fd)
            except OSError:
                pass
            finally:
                os.close(dir_fd)

    def _run_locked(self, operation):
        fd = self._acquire_lock()
        temp_files: list[str] = []
        try:
            self._fail("after_lock")
            result, new_state = operation()
            if new_state is not None:
                self._write_state(new_state, temp_files)
            return result
        finally:
            for temp_path in temp_files:
                try:
                    os.unlink(temp_path)
                except OSError:
                    pass
            self._release_lock(fd)

    def _clock_now(self):
        try:
            value = self._clock()
        except Exception as exc:
            raise _error("INVALID_DEPENDENCY", "clock raised an exception", {"reason": str(exc)}) from exc
        if not _is_finite_number(value):
            raise _error("INVALID_DEPENDENCY", "clock returned a non-finite number", {})
        return value

    def _canonical_payload(self, payload) -> str:
        try:
            canonical = _canonical_dumps(payload)
        except (TypeError, ValueError) as exc:
            raise _error("INVALID_INPUT", f"payload is not JSON-serializable: {exc}", {}) from exc
        if len(canonical.encode("utf-8")) > self._limits.max_payload_bytes:
            raise _error(
                "CAPACITY_EXCEEDED",
                "payload exceeds max_payload_bytes",
                {"max_payload_bytes": self._limits.max_payload_bytes},
            )
        return canonical

    @staticmethod
    def _public_message(message: dict) -> dict:
        return {
            "message_id": message["message_id"],
            "payload": message["payload"],
            "status": message["status"],
            "available_at": message["available_at"],
            "sequence": message["sequence"],
            "attempts": message["attempts"],
            "last_error": message["last_error"],
        }

    @staticmethod
    def _clear_lease(message: dict) -> None:
        message.pop("lease_token", None)
        message.pop("worker_id", None)
        message.pop("expires_at", None)

    # -- public API ----------------------------------------------------

    def initialize(self) -> dict:
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as exc:
            raise _error("INTERNAL_ERROR", f"could not create root directory: {exc}", {}) from exc

        def operation():
            try:
                self._read_state()
            except SpoolError as exc:
                if exc.code != "NOT_INITIALIZED":
                    raise
            else:
                raise _error("ALREADY_INITIALIZED", "spool is already initialized", {"root": self._root})
            initial = {"schema_version": _SCHEMA_VERSION, "next_sequence": 1, "messages": {}}
            return initial, initial

        return self._run_locked(operation)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        message_id = _require_id(message_id, "message_id")
        canonical_payload = self._canonical_payload(payload)
        explicit = available_at is not None
        if explicit and not _is_finite_number(available_at):
            raise _error("INVALID_INPUT", "available_at must be a finite number", {"field": "available_at"})

        def operation():
            state = self._read_state()
            messages = state["messages"]
            existing = messages.get(message_id)
            if existing is not None:
                same_payload = _canonical_dumps(existing["payload"]) == canonical_payload
                if same_payload and (not explicit or existing["available_at"] == available_at):
                    return self._public_message(existing), None
                raise _error(
                    "IDEMPOTENCY_CONFLICT",
                    "message id already enqueued with different payload or available_at",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise _error(
                    "CAPACITY_EXCEEDED",
                    "message capacity reached",
                    {"max_messages": self._limits.max_messages},
                )
            if explicit:
                effective_available_at = available_at
            else:
                effective_available_at = self._clock_now()
            record = {
                "message_id": message_id,
                "payload": json.loads(canonical_payload),
                "status": "pending",
                "available_at": effective_available_at,
                "sequence": state["next_sequence"],
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = record
            state["next_sequence"] += 1
            return self._public_message(record), state

        return self._run_locked(operation)

    def claim(self, worker_id: str) -> dict | None:
        worker_id = _require_id(worker_id, "worker_id")

        def operation():
            state = self._read_state()
            now = self._clock_now()
            candidates = [
                message
                for message in state["messages"].values()
                if message["status"] == "pending" and message["available_at"] <= now
            ]
            if not candidates:
                return None, None
            best = min(candidates, key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            best["status"] = "leased"
            best["attempts"] += 1
            token = secrets.token_hex(16)
            best["lease_token"] = token
            best["worker_id"] = worker_id
            best["expires_at"] = now + self._limits.lease_seconds
            result = self._public_message(best)
            result["lease_token"] = token
            return result, state

        return self._run_locked(operation)

    def ack(self, message_id: str, lease_token: str) -> dict:
        message_id = _require_id(message_id, "message_id")
        if not isinstance(lease_token, str):
            raise _error("INVALID_INPUT", "lease_token must be a string", {"field": "lease_token"})

        def operation():
            state = self._read_state()
            message = state["messages"].get(message_id)
            if message is None:
                raise _error("NOT_FOUND", "message not found", {"message_id": message_id})
            if message["status"] != "leased":
                raise _error("INVALID_STATE", f"message is not leased (status {message['status']})", {"message_id": message_id})
            if not hmac.compare_digest(
                lease_token.encode("utf-8"), message["lease_token"].encode("utf-8")
            ):
                raise _error("UNAUTHORIZED", "lease token does not match", {})
            message["status"] = "acked"
            self._clear_lease(message)
            return self._public_message(message), state

        return self._run_locked(operation)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        message_id = _require_id(message_id, "message_id")
        if not isinstance(lease_token, str):
            raise _error("INVALID_INPUT", "lease_token must be a string", {"field": "lease_token"})
        if not isinstance(error, str) or error == "":
            raise _error("INVALID_INPUT", "error must be a non-empty string", {"field": "error"})

        def operation():
            state = self._read_state()
            message = state["messages"].get(message_id)
            if message is None:
                raise _error("NOT_FOUND", "message not found", {"message_id": message_id})
            if message["status"] != "leased":
                raise _error("INVALID_STATE", f"message is not leased (status {message['status']})", {"message_id": message_id})
            if not hmac.compare_digest(
                lease_token.encode("utf-8"), message["lease_token"].encode("utf-8")
            ):
                raise _error("UNAUTHORIZED", "lease token does not match", {})
            message["last_error"] = error
            self._clear_lease(message)
            if message["attempts"] >= self._limits.max_attempts:
                message["status"] = "dead"
            else:
                message["status"] = "pending"
                message["available_at"] = self._clock_now() + self._limits.retry_delay
            return self._public_message(message), state

        return self._run_locked(operation)

    def recover(self) -> dict:
        def operation():
            state = self._read_state()
            now = self._clock_now()
            recovered = 0
            for message in state["messages"].values():
                if message["status"] == "leased" and now >= message["expires_at"]:
                    self._clear_lease(message)
                    if message["attempts"] >= self._limits.max_attempts:
                        message["status"] = "dead"
                    else:
                        message["status"] = "pending"
                        message["available_at"] = now
                    recovered += 1
            if recovered == 0:
                return {"recovered": 0}, None
            return {"recovered": recovered}, state

        return self._run_locked(operation)

    def get(self, message_id: str) -> dict:
        message_id = _require_id(message_id, "message_id")

        def operation():
            state = self._read_state()
            message = state["messages"].get(message_id)
            if message is None:
                raise _error("NOT_FOUND", "message not found", {"message_id": message_id})
            return self._public_message(message), None

        return self._run_locked(operation)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None and status not in _STATUSES:
            raise _error("INVALID_INPUT", "status must be one of pending, leased, acked, dead", {"field": "status"})

        def operation():
            state = self._read_state()
            selected = [
                message
                for message in state["messages"].values()
                if status is None or message["status"] == status
            ]
            selected.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return [self._public_message(message) for message in selected], None

        return self._run_locked(operation)

