"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time

from . import Limits, Spool, SpoolError

_OPTIONAL_INPUT_COMMANDS = frozenset({"init", "recover", "list"})
_STORAGE_CODES = frozenset({"CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR"})

_COMMAND_FIELDS = {
    "init": ((), ()),
    "enqueue": (("message_id", "payload"), ("available_at",)),
    "claim": (("worker_id",), ()),
    "ack": (("message_id", "lease_token"), ()),
    "fail": (("message_id", "lease_token", "error"), ()),
    "recover": ((), ()),
    "show": (("message_id",), ()),
    "list": ((), ("status",)),
}


def _emit(payload: object) -> None:
    text = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    sys.stdout.buffer.write(text.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()


def _fail(code: str, message: str, details: dict[str, object] | None = None) -> int:
    _emit({"ok": False, "error": {"code": code, "message": message, "details": details or {}}})
    return 3 if code in _STORAGE_CODES else 2


def _parse_args(argv: list[str]):
    root = None
    rest: list[str] = []
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--root":
            if index + 1 >= len(argv):
                return None, None
            root = argv[index + 1]
            index += 2
        else:
            rest.append(arg)
            index += 1
    if root is None or len(rest) != 1:
        return None, None
    return root, rest[0]


def _read_input(command: str) -> dict:
    raw = sys.stdin.buffer.read()
    text = raw.decode("utf-8")
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        if command in _OPTIONAL_INPUT_COMMANDS:
            return {}
        raise ValueError("expected exactly one non-empty stdin line")
    if len(lines) != 1:
        raise ValueError("expected exactly one non-empty stdin line")
    obj = json.loads(lines[0])
    if not isinstance(obj, dict):
        raise ValueError("stdin must be a JSON object")
    return obj


def main() -> None:
    root, command = _parse_args(sys.argv[1:])
    if root is None or command not in _COMMAND_FIELDS:
        sys.exit(_fail("INVALID_INPUT", "usage: python -m src.delivery_spool --root <path> <command>", {}))
    try:
        obj = _read_input(command)
    except Exception as exc:
        sys.exit(_fail("INVALID_INPUT", f"invalid input: {exc}", {}))
    required, optional = _COMMAND_FIELDS[command]
    keys = set(obj.keys())
    if not set(required) <= keys or not keys <= set(required) | set(optional):
        sys.exit(_fail(
            "INVALID_INPUT",
            f"command {command} has missing or unknown fields",
            {"command": command, "required": sorted(required), "optional": sorted(optional)},
        ))
    try:
        spool = Spool(root, clock=time.time, limits=Limits(), lock_timeout=10.0, failpoint=None)
        if command == "init":
            result = spool.initialize()
        elif command == "enqueue":
            result = spool.enqueue(obj["message_id"], obj["payload"], obj.get("available_at"))
        elif command == "claim":
            result = spool.claim(obj["worker_id"])
        elif command == "ack":
            result = spool.ack(obj["message_id"], obj["lease_token"])
        elif command == "fail":
            result = spool.fail(obj["message_id"], obj["lease_token"], obj["error"])
        elif command == "recover":
            result = spool.recover()
        elif command == "show":
            result = spool.get(obj["message_id"])
        else:
            result = spool.list_messages(obj.get("status"))
    except SpoolError as exc:
        sys.exit(_fail(exc.code, exc.message, exc.details))
    except Exception as exc:
        sys.exit(_fail("INTERNAL_ERROR", f"unexpected failure: {exc}", {}))
    _emit({"ok": True, "result": result})
    sys.exit(0)


if __name__ == "__main__":
    main()

